     1	import { Autopay } from "../domain/autopay";
     2	import { Member } from "../domain/member";
     3	import { Reminder, ReminderKind, reminderKey } from "../domain/reminder";
     4	import { renderMessage } from "../push/messageTemplates";
     5	import { AutopayRepository } from "../repository/autopayRepository";
     6	import { MemberRepository } from "../repository/memberRepository";
     7	import { SendTimePolicy } from "../scheduling/sendTime";
     8	import { at, dateOf, dayOfMonth, LocalDate, LocalDateTime } from "../time/localTime";
     9	
    10	export interface DayPlan {
    11	  reminders: Reminder[];
    12	  skippedOptOut: number;
    13	}
    14	
    15	/** 어떤 알림을 언제 보낼지 정한다(예약은 하지 않는다). */
    16	export class ReminderPlanner {
    17	  constructor(
    18	    private readonly members: MemberRepository,
    19	    private readonly autopays: AutopayRepository,
    20	    private readonly policy: SendTimePolicy,
    21	    private readonly retryNoticeLeadMinutes: number,
    22	  ) {}
    23	
    24	  /** 그날 출금되는 계약마다 출금 예정 알림 1건 */
    25	  billDue(date: LocalDate): DayPlan {
    26	    const reminders: Reminder[] = [];
    27	    let skippedOptOut = 0;
    28	    const seen = new Set<string>();
    29	    for (const a of this.autopays.billingOn(dayOfMonth(date))) {
    30	      const m = this.members.find(a.memberId);
    31	      if (!m) continue;
    32	      if (!m.pushOptIn) {
    33	        skippedOptOut++;
    34	        continue;
    35	      }
    36	      const dueAt = at(date, a.billingTime);
    37	      const r = this.build("BILL_DUE", a, m, dueAt, m.leadMinutes);
    38	      if (seen.has(r.key)) continue;
    39	      seen.add(r.key);
    40	      reminders.push(r);
    41	    }
    42	    return { reminders, skippedOptOut };
    43	  }
    44	
    45	  /** 출금 실패 → 재출금 안내 1건(수신 거부면 없음) */
    46	  retryNotice(autopay: Autopay, retryAt: LocalDateTime): Reminder | undefined {
    47	    const m = this.members.find(autopay.memberId);
    48	    if (!m || !m.pushOptIn) return undefined;
    49	    return this.build("RETRY", autopay, m, retryAt, this.retryNoticeLeadMinutes);
    50	  }
    51	
    52	  private build(kind: ReminderKind, a: Autopay, m: Member, dueAt: LocalDateTime, lead: number): Reminder {
    53	    return {
    54	      key: reminderKey(kind, a.id, dueAt),
    55	      kind,
    56	      memberId: m.id,
    57	      autopayId: a.id,
    58	      device: m.device,
    59	      dueAt,
    60	      sendAt: this.policy.sendAt(dueAt, lead),
    61	      planDate: dateOf(dueAt),
    62	      message: renderMessage(kind, a, dueAt),
    63	    };
    64	  }
    65	}
