     1	import { validateFailure } from "../domain/autopay";
     2	import { Reminder } from "../domain/reminder";
     3	import { PushqClient, PushqError } from "../push/pushqClient";
     4	import { AutopayRepository } from "../repository/autopayRepository";
     5	import { ReminderRepository } from "../repository/reminderRepository";
     6	import { addMinutes, compare, LocalDate, LocalDateTime } from "../time/localTime";
     7	import { ReminderPlanner } from "./reminderPlanner";
     8	
     9	export interface PlanResult {
    10	  date: LocalDate;
    11	  planned: number;
    12	  scheduled: number;
    13	  alreadyScheduled: number;
    14	  skippedOptOut: number;
    15	}
    16	
    17	/** 알림 예약·취소와 벤더 시계 진행 */
    18	export class ReminderService {
    19	  private clock: LocalDateTime | undefined;
    20	
    21	  constructor(
    22	    private readonly planner: ReminderPlanner,
    23	    private readonly autopays: AutopayRepository,
    24	    private readonly reminders: ReminderRepository,
    25	    private readonly push: PushqClient,
    26	    private readonly retryDelayMinutes: number,
    27	  ) {}
    28	
    29	  now(): LocalDateTime | undefined {
    30	    return this.clock;
    31	  }
    32	
    33	  /** 하루치 출금 예정 알림을 예약한다. 다시 불러도 이미 예약한 알림은 건너뛴다. */
    34	  planDay(date: LocalDate): PlanResult {
    35	    const plan = this.planner.billDue(date);
    36	    let scheduled = 0;
    37	    let already = 0;
    38	    for (const r of plan.reminders) {
    39	      if (this.reminders.has(r.key)) {
    40	        already++;
    41	        continue;
    42	      }
    43	      this.schedule(r);
    44	      scheduled++;
    45	    }
    46	    return { date, planned: plan.reminders.length, scheduled, alreadyScheduled: already, skippedOptOut: plan.skippedOptOut };
    47	  }
    48	
    49	  /** 출금 실패를 기록하고 재출금 안내를 예약한다. */
    50	  recordFailure(autopayId: string, body: unknown): { retryAt: LocalDateTime; notice?: { key: string; sendAt: LocalDateTime } } {
    51	    const a = this.autopays.find(autopayId);
    52	    if (!a) throw new Error(`autopay ${autopayId} not found`);
    53	    const f = validateFailure(autopayId, body);
    54	    this.autopays.addFailure(f);
    55	    const retryAt = addMinutes(f.failedAt, this.retryDelayMinutes);
    56	    const r = this.planner.retryNotice(a, retryAt);
    57	    if (!r || this.reminders.has(r.key)) return { retryAt };
    58	    this.schedule(r);
    59	    return { retryAt, notice: { key: r.key, sendAt: r.sendAt } };
    60	  }
    61	
    62	  /** 계약 해지 — 아직 나가지 않은 알림 예약을 취소한다. */
    63	  cancelAutopay(autopayId: string): { cancelled: number } {
    64	    this.autopays.deactivate(autopayId);
    65	    let cancelled = 0;
    66	    for (const r of this.reminders.byAutopay(autopayId)) {
    67	      if (!r.ticket || (this.clock && compare(r.sendAt, this.clock) <= 0)) continue;
    68	      try {
    69	        this.push.cancel(r.ticket);
    70	        cancelled++;
    71	      } catch (e) {
    72	        // 이미 나간 티켓은 벤더가 E31 을 준다 — 취소할 것이 없으므로 넘어간다.
    73	        if (!(e instanceof PushqError && e.code === "E31")) throw e;
    74	      }
    75	      this.reminders.remove(r.key);
    76	    }
    77	    return { cancelled };
    78	  }
    79	
    80	  /** 벤더 시계를 until 까지 진행한다(운영에서는 벤더가 스스로 흐른다). */
    81	  advance(until: LocalDateTime): { delivered: number } {
    82	    const delivered = this.push.advance(until);
    83	    this.clock = until;
    84	    return { delivered };
    85	  }
    86	
    87	  private schedule(r: Reminder): void {
    88	    const ticket = this.push.schedule(r.device, r.sendAt, r.key, r.message);
    89	    this.reminders.save({ ...r, ticket });
    90	  }
    91	}
