     1	import { Reminder } from "../domain/reminder";
     2	import { LocalDate } from "../time/localTime";
     3	
     4	/** 예약해 둔 알림 — 키 단위로 한 번만 저장된다. */
     5	export class ReminderRepository {
     6	  private readonly rows = new Map<string, Reminder>();
     7	
     8	  has(key: string): boolean {
     9	    return this.rows.has(key);
    10	  }
    11	
    12	  save(r: Reminder): void {
    13	    this.rows.set(r.key, { ...r });
    14	  }
    15	
    16	  find(key: string): Reminder | undefined {
    17	    const r = this.rows.get(key);
    18	    return r ? { ...r } : undefined;
    19	  }
    20	
    21	  byPlanDate(date: LocalDate): Reminder[] {
    22	    return [...this.rows.values()]
    23	      .filter((r) => r.planDate === date)
    24	      .sort((a, b) => (a.sendAt < b.sendAt ? -1 : a.sendAt > b.sendAt ? 1 : a.key < b.key ? -1 : 1))
    25	      .map((r) => ({ ...r }));
    26	  }
    27	
    28	  byAutopay(autopayId: string): Reminder[] {
    29	    return [...this.rows.values()].filter((r) => r.autopayId === autopayId).map((r) => ({ ...r }));
    30	  }
    31	
    32	  remove(key: string): void {
    33	    this.rows.delete(key);
    34	  }
    35	}

