    11	  memberId: string;
    12	  kind: string;
    13	  dueAt: LocalDateTime;
    14	  sendAt: LocalDateTime;
    15	  ticket: string;
    16	  device: string;
    17	  status: LineStatus;
    18	  deliveredAt?: LocalDateTime;
    19	}
    20	
    21	export interface ReminderReport {
    22	  date: LocalDate;
    23	  asOf: LocalDateTime | null;
    24	  planned: number;
    25	  delivered: number;
    26	  missing: number;
    27	  pending: number;
