     1	import { addMinutes, fromEpochSeconds, LocalDateTime, toEpochSeconds } from "../time/localTime";
     2	import { QuietHours } from "./quietHours";
     3	
     4	/** pushq 는 5분 경계(분이 5의 배수, 초 00)가 아닌 예약 시각을 티켓만 주고 큐에 넣지 않는다. */
     5	const PUSH_SLOT_SECONDS = 300;
     6	
     7	/**
     8	 * 알림 발송 시각 정책.
     9	 * - 안내 대상 시각(출금·재출금)보다 lead 분 앞서 보낸다.
    10	 * - 야간 방해 금지 구간에 걸리면 전날 저녁으로 당긴다.
    11	 * - 푸시 예약 시각은 직전 5분 경계로 내린다(늦게 보내지 않는다).
    12	 */
    13	export class SendTimePolicy {
    14	  constructor(private readonly quiet: QuietHours) {}
    15	
    16	  sendAt(dueAt: LocalDateTime, leadMinutes: number): LocalDateTime {
    17	    const nominal = addMinutes(dueAt, -leadMinutes);
    18	    return floorToSlot(this.quiet.pullBack(nominal));
    19	  }
    20	}
    21	
    22	function floorToSlot(t: LocalDateTime): LocalDateTime {
    23	  const s = toEpochSeconds(t);
    24	  return fromEpochSeconds(s - (s % PUSH_SLOT_SECONDS));
    25	}
