     1	import { addMinutes, fromEpochSeconds, LocalDateTime, toEpochSeconds } from "../time/localTime";
     2	import { QuietHours } from "./quietHours";
     3	
     4	/** pushq 는 5분 경계(분이 5의 배수, 초 00)가 아닌 예약 시각을 티켓만 주고 큐에 넣지 않는다. */
     5	const PUSH_SLOT_SECONDS = 300;
     6	
     7	/**
     8	 * 알림 발송 시각 정책.
     9	 * - 안내 대상 시각(출금·재출금)보다 lead 분 앞서 보낸다.
    10	 * - 야간 방해 금지 구간에 걸리면 전날 저녁으로 당긴다.
    11	 * - 푸시 예약 시각은 직전 5분 경계로 내린다(늦게 보내지 않는다).
    12	 */
    13	export class SendTimePolicy {
    14	  constructor(private readonly quiet: QuietHours) {}
    15	
    16	  sendAt(dueAt: LocalDateTime, leadMinutes: number): LocalDateTime {
    17	    const nominal = addMinutes(dueAt, -leadMinutes);
    18	    return floorToSlot(this.quiet.pullBack(nominal));
    19	  }
    20	}
    21	
    22	function floorToSlot(t: LocalDateTime): LocalDateTime {
    23	  const s = toEpochSeconds(t);
    24	  return fromEpochSeconds(s - (s % PUSH_SLOT_SECONDS));
    25	}
=== src/scheduling/quietHours.ts
     1	import { at, dateOf, LocalDateTime, previousDate, timeOf } from "../time/localTime";
     2	
     3	/**
     4	 * 야간 방해 금지 — [start, end) 구간(자정을 넘는다)에 걸린 알림은
     5	 * 늦게 보내지 않고 직전 저녁(fallback 시각)으로 당긴다. 금융 알림은 늦으면 안 되기 때문이다.
     6	 */
     7	export class QuietHours {
     8	  constructor(
     9	    private readonly start: string,
    10	    private readonly end: string,
    11	    private readonly fallback: string,
    12	  ) {}
    13	
    14	  contains(t: LocalDateTime): boolean {
    15	    const hm = timeOf(t);
    16	    return this.start > this.end ? hm >= this.start || hm < this.end : hm >= this.start && hm < this.end;
    17	  }
    18	
    19	  /** 구간 밖이면 그대로, 안이면 직전 저녁 fallback 시각 */
    20	  pullBack(t: LocalDateTime): LocalDateTime {
    21	    if (!this.contains(t)) return t;
    22	    const d = dateOf(t);
    23	    const eveningOf = timeOf(t) >= this.start ? d : previousDate(d);
    24	    return at(eveningOf, this.fallback);
    25	  }
    26	}
