     8	  create(input: Omit<Autopay, "id" | "active">): Autopay {
     9	    this.seq++;
    10	    const a: Autopay = { ...input, id: `AP${String(this.seq).padStart(5, "0")}`, active: true };
    11	    this.rows.set(a.id, a);
