    14	
    15	  find(id: string): Autopay | undefined {
    16	    const a = this.rows.get(id);
    17	    return a ? { ...a } : undefined;
    18	  }
    19	
    20	  deactivate(id: string): void {
    21	    const a = this.rows.get(id);
    22	    if (a) a.active = false;
    23	  }
    24	
    25	  /** 해당 출금일에 출금되는 활성 계약 — 등록 순 */
    26	  billingOn(day: number): Autopay[] {
    27	    return [...this.rows.values()].filter((a) => a.active && a.billingDay === day).map((a) => ({ ...a }));
