/** 출금 실패를 기록하고 재출금 안내를 예약한다. */
recordFailure(autopayId: string, body: unknown): { retryAt: LocalDateTime; notice?: { key: string; sendAt: LocalDateTime } } {
  const a = this.autopays.find(autopayId);
  if (!a) throw new Error(`autopay ${autopayId} not found`);
  const f = validateFailure(autopayId, body);
  const episodes = this.retryEpisodes(autopayId);
  this.autopays.addFailure(f);
  const open = episodes[episodes.length - 1];
  // 재출금이 잡혀 있는 동안 들어온 통보는 재통보다 — 새 재출금을 잡지 않는다(docs/ops/bank-failure-feed.md)
  if (open && compare(f.failedAt, open.retryAt) < 0) return { retryAt: open.retryAt };
  const retryAt = addMinutes(f.failedAt, this.retryDelayMinutes);
  const r = this.planner.retryNotice(a, retryAt, episodes.length + 1);
  if (!r || this.reminders.has(r.key)) return { retryAt };
  this.schedule(r);
  return { retryAt, notice: { key: r.key, sendAt: r.sendAt } };
}

/** 지금까지 잡힌 재출금 건들의 재출금 시각 목록(등록 순). 재통보는 건을 늘리지 않는다. */
private retryEpisodes(autopayId: string): LocalDateTime[] {
  const retryAts: LocalDateTime[] = [];
  for (const f of this.autopays.failuresOf(autopayId)) {
    const open = retryAts[retryAts.length - 1];
    if (open && compare(f.failedAt, open) < 0) continue;
    retryAts.push(addMinutes(f.failedAt, this.retryDelayMinutes));
  }
  return retryAts;
}

